-- Classic 1.60 (WoW Forever): spawns of the dungeon Hall of Thanes (map 3065) from ymir sniffs of the official beta
-- (classic_re/sniff/sniff_import_instance.py): every placed creature and gameobject, merged over the instances seen; event
-- spawns (only seen being created in view) and summons are left to the scripts. Safe to run again.
DELETE FROM `creature` WHERE `map` = 3065 OR `guid` BETWEEN 21400000 AND 21499999;
DELETE FROM `gameobject` WHERE `map` = 3065 OR `guid` BETWEEN 21400000 AND 21499999;
DELETE FROM `creature_addon` WHERE `guid` BETWEEN 21400000 AND 21499999;
DELETE FROM `waypoint_path_node` WHERE `PathId` BETWEEN 214000000 AND 214999999;
DELETE FROM `waypoint_path` WHERE `PathId` BETWEEN 214000000 AND 214999999;
-- patrols (walking routes the creature repeated in the sniff)
DELETE FROM `creature_formations` WHERE `leaderGUID` BETWEEN 21400000 AND 21499999 OR `memberGUID` BETWEEN 21400000 AND 21499999;
-- formations (a mob walking whenever a patrolling mob next to it walks follows it; with --assist: guards fighting with their boss)
